    fun ui(key: String, locale: AppLocale): String =
        ui[key]?.get(locale.code) ?: ui[key]?.get("en") ?: key

    fun festivalGreeting(festivalId: String, locale: AppLocale): String =
        festivals[festivalId]?.get(locale.code) ?: festivals[festivalId]?.get("en") ?: ""

    fun verdictTitle(id: String, locale: AppLocale, fallback: String): String {
        val baseId = id.substringBefore(".")
        return verdictTitles[id]?.get(locale.code)
            ?: verdictTitles[baseId]?.get(locale.code)
            ?: fallback
    }

    fun chatLanguageInstruction(locale: AppLocale): String = when (locale) {
        AppLocale.EN -> "Respond in English."
        AppLocale.HI -> "हमेशा हिन्दी में जवाब दें। Indian-English idioms OK."
        AppLocale.TE -> "ఎప్పుడూ తెలుగులో సమాధానం ఇవ్వండి. Idioms like 'enda mandipotundi' welcome."
        AppLocale.TA -> "எப்போதும் தமிழில் பதிலளிக்கவும்."
    }
}
